async function buildSite(config: GeneratorConfig): Promise<void> {
  const posts = await discoverPosts(config.sourceDir);
  const published = posts.filter(p => !p.frontmatter.draft);
  const templates = await setupTemplates(config.templateDir);

  for (const post of published) {
    post.html = convertMarkdown(post.content);
    const rendered = templates.render(post);
    await writePost(post, rendered, config.outputDir);
  }

  await generateIndex(published, templates, config);
  await generateTagPages(published, templates, config);
  await generateRss(published, config);
}
```

