import matter from 'gray-matter';
import { readFile } from 'node:fs/promises';
import { Frontmatter, Page } from '../types';

export async function parseFrontmatter(filePath: string): Promise<{ data: Frontmatter; content: string }> {
  const source = await readFile(filePath, 'utf-8');
  const parsed = matter(source);
  return {
    data: parsed.data as Frontmatter,
    content: parsed.content.trim(),
  };
}

export function extractSlug(filePath: string): string {
  const base = filePath.split('/').pop() ?? filePath;
  return base.replace(/\.md$/i, '');
}

export function makePage(slug: string, filePath: string, data: Frontmatter, rawContent: string): Page {
  return {
    slug,
    sourcePath: filePath,
    frontmatter: data,
    rawContent,
    html: '',
  };
}

export function isValidPost(data: Frontmatter): boolean {
  return typeof data.title === 'string' && data.title.length > 0;
}

export function isDraft(data: Frontmatter): boolean {
  return data.draft === true;
}

import { Marked } from 'marked';
import { markedHighlight } from 'marked-highlight';
import hljs from 'highlight.js';

const marked = new Marked(
  markedHighlight({
    langPrefix: 'hljs language-',
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  }),
);

export function convertMarkdown(markdown: string): string {
  return marked.parse(markdown) as string;
}
